// Some portions generated by Codex
package org.eclipse.rdf4j.query.parser.gql;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertTrue;

import org.eclipse.rdf4j.model.Literal;
import org.eclipse.rdf4j.model.Value;
import org.eclipse.rdf4j.query.QueryLanguage;
import org.eclipse.rdf4j.query.TupleQueryResult;
import org.eclipse.rdf4j.repository.RepositoryConnection;
import org.eclipse.rdf4j.repository.sail.SailRepository;
import org.eclipse.rdf4j.sail.memory.MemoryStore;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;

class GqlExpressionEvaluationTest {

	private SailRepository repository;

	private RepositoryConnection connection;

	@BeforeEach
	void setUp() {
		repository = new SailRepository(new MemoryStore());
		repository.init();
		connection = repository.getConnection();
	}

	@AfterEach
	void tearDown() {
		connection.close();
		repository.shutDown();
	}

	@Test
	void preservesArithmeticPrecedenceAndSigns() {
		assertEquals(14, ((Literal) value("2 + 3 * 4")).intValue());
		assertEquals(20, ((Literal) value("(2 + 3) * 4")).intValue());
		assertEquals(-6, ((Literal) value("-2 * +3")).intValue());
		assertEquals(4.5, ((Literal) value("9 / 2")).doubleValue());
	}

	@Test
	void moduloPreservesNumericTypesAndTheDividendSign() {
		assertEquals(1, ((Literal) value("7 % 3")).intValue());
		assertEquals(-1, ((Literal) value("-7 % 3")).intValue());
		assertEquals(1, ((Literal) value("7 % -3")).intValue());
		assertEquals(1.5, ((Literal) value("7.5 % 2")).doubleValue());
		assertEquals(1, ((Literal) value("MOD(7, 3)")).intValue());
		assertNull(value("7 % 0"));
		assertNull(value("NULL % 3"));
	}

	@Test
	void booleanPrecedenceAndUnknownAreThreeValued() {
		assertTrue(booleanValue("TRUE OR FALSE AND FALSE"));
		assertTrue(booleanValue("NOT TRUE OR TRUE"));
		assertTrue(booleanValue("TRUE XOR FALSE"));
		assertFalse(booleanValue("TRUE XOR TRUE"));
		assertNull(value("TRUE XOR NULL"));
		assertTrue(booleanValue("TRUE OR NULL"));
		assertFalse(booleanValue("FALSE AND NULL"));
	}

	@Test
	void nullPredicatesAlwaysReturnBooleans() {
		assertTrue(booleanValue("NULL IS NULL"));
		assertFalse(booleanValue("(NULL IS NULL) IS NULL"));
		assertTrue(booleanValue("(NULL IS NULL) IS NOT NULL"));
		assertTrue(booleanValue("NULL IS NOT TRUE"));
		assertTrue(booleanValue("NULL IS NOT FALSE"));
		assertFalse(booleanValue("FALSE IS TRUE"));
	}

	@Test
	void membershipKeepsUnknownUnlessAnEqualElementExists() {
		assertTrue(booleanValue("2 IN [1, 2, NULL]"));
		assertNull(value("9 IN [1, 2, NULL]"));
		assertFalse(booleanValue("NULL IN []"));
		assertTrue(booleanValue("9 NOT IN [1, 2]"));
	}

	@Test
	void betweenUsesInclusiveBounds() {
		assertTrue(booleanValue("1 BETWEEN 0 AND 1"));
		assertFalse(booleanValue("1 NOT BETWEEN 0 AND 1"));
		assertNull(value("1 BETWEEN NULL AND 2"));
	}

	@Test
	void searchedCaseSkipsFalseAndUnknownBranches() {
		assertEquals("good", value("CASE WHEN NULL THEN 'bad' WHEN TRUE THEN 'good' ELSE 'bad' END").stringValue());
		assertEquals("2", value("CASE WHEN FALSE THEN 1 / 0 ELSE 2 END").stringValue());
		assertNull(value("CASE WHEN FALSE THEN 1 END"));
	}

	@Test
	void simpleCaseUsesValueComparison() {
		assertEquals("good", value("CASE 2 WHEN 1 THEN 'bad' WHEN 2 THEN 'good' END").stringValue());
		assertEquals("unknown", value("CASE NULL WHEN NULL THEN 'bad' ELSE 'unknown' END").stringValue());
	}

	@Test
	void concatenatesStringsAndPropagatesNull() {
		assertEquals("ab", value("'a' || 'b'").stringValue());
		assertNull(value("'a' || NULL"));
	}

	private boolean booleanValue(String expression) {
		return ((Literal) value(expression)).booleanValue();
	}

	private Value value(String expression) {
		try (TupleQueryResult result = connection.prepareTupleQuery(QueryLanguage.GQL,
				"RETURN " + expression + " AS value").evaluate()) {
			assertTrue(result.hasNext(), expression);
			Value value = result.next().getValue("value");
			assertFalse(result.hasNext(), expression);
			return value;
		}
	}
}
